.ds-button{font-family:var(--font-ui, "Instrument Sans Variable", "Noto Serif SC", system-ui, sans-serif);color:var(--ink, #f0f3f5);border:0;cursor:pointer;}.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 48px;
  padding: 0 22px;
  border-radius: var(--r, 10px);
  background: var(--accent, #b3d2f5);
  color: var(--on-accent, #102238);
  font-weight: 500;
  font-size: 16px;
  white-space: nowrap;
  transition:
    background-color 160ms ease,
    transform 160ms var(--ease-out, cubic-bezier(0.23, 1, 0.32, 1)),
    opacity 160ms ease;
}.ds-button:active:not(:disabled) {
  transform: scale(0.97);
}.ds-button:disabled {
  opacity: 0.38;
}@media(hover:hover) and (pointer:fine){.ds-button:hover:not(:disabled) {
    background: var(--accent-hover, #d2e5fc);
  }}.ds-button:focus-visible,.ds-field input:focus-visible,.ds-nav button:focus-visible,.ds-chip:focus-visible,.ds-choice:focus-visible,.ds-audio-disc:focus-visible,.ds-text-teaser:focus-visible{outline:2px solid var(--accent, #b3d2f5);outline-offset:3px}@media(prefers-reduced-motion:reduce){button:active{transform:none!important}button{transition-duration:1ms!important;animation:none!important}}

