.ds-field {
  display: grid;
  gap: 8px;
  font-size: 15px;
  font-weight: 500;
  color: var(--ink-2, #c7d3df);
}.ds-field{font-family:var(--font-ui, "Instrument Sans Variable", "Noto Serif SC", system-ui, sans-serif)}.ds-field input{font-family:var(--font-ui, "Instrument Sans Variable", "Noto Serif SC", system-ui, sans-serif);color-scheme:dark;min-height:48px;padding:0 14px;border:1px solid var(--rule-strong, #657f98);border-radius:var(--r, 10px);background:var(--sheet, #17263a);font-size:17px;font-weight:400;color:var(--ink, #f0f3f5);caret-color:var(--accent, #b3d2f5)}.ds-field input::placeholder{color:var(--ink-4, #9aafc3);opacity:1}.ds-field input:focus-visible{outline:2px solid var(--accent, #b3d2f5);outline-offset:0}

.ds-main-nav button{font-family:var(--font-ui, "Instrument Sans Variable", "Noto Serif SC", system-ui, sans-serif);color:var(--ink, #f0f3f5);border:0;cursor:pointer;background:transparent}.ds-main-nav {
  display: flex;
  gap: 4px;
  justify-content: center;
}.ds-main-nav button {
  position: relative;
  height: var(--mast, 64px);
  padding: 0 12px;
  font-size: 15px;
  font-weight: 500;
  color: var(--ink-3, #aabccd);
  white-space: nowrap;
  transition: color 160ms ease;
}.ds-main-nav button::after {
  content: "";
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: -1px;
  height: 2px;
  background: var(--ink, #f0f3f5);
  transform: scaleX(0);
  transition: transform 220ms var(--ease-out, cubic-bezier(0.23, 1, 0.32, 1));
}.ds-main-nav button.ds-active {
  color: var(--ink, #f0f3f5);
}.ds-main-nav button.ds-active::after {
  transform: scaleX(1);
}@media(hover:hover) and (pointer:fine){.ds-main-nav button:hover {
    color: var(--ink, #f0f3f5);
  }}.ds-button:focus-visible,.ds-field input:focus-visible,.ds-nav button:focus-visible,.ds-chip:focus-visible,.ds-choice:focus-visible,.ds-audio-disc:focus-visible,.ds-text-teaser:focus-visible{outline:2px solid var(--accent, #b3d2f5);outline-offset:3px}@media(prefers-reduced-motion:reduce){button:active{transform:none!important}button{transition-duration:1ms!important;animation:none!important}}

.ds-chip{font-family:var(--font-ui, "Instrument Sans Variable", "Noto Serif SC", system-ui, sans-serif);color:var(--ink, #f0f3f5);border:0;cursor:pointer;background:transparent}.ds-chip:active{transform:scale(.96)}.ds-chip-picker button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 42px;
  padding: 0 14px;
  border-radius: var(--r, 10px);
  box-shadow: inset 0 0 0 1px var(--rule-strong, #657f98);
  font-size: 15px;
  font-weight: 500;
  color: var(--ink-2, #c7d3df);
  transition:
    background-color 160ms ease,
    transform 160ms var(--ease-out, cubic-bezier(0.23, 1, 0.32, 1));
}.ds-chip-picker button[aria-pressed="true"] {
  background: var(--ink, #f0f3f5);
  color: var(--paper, #101b2b);
  box-shadow: none;
}.ds-button:focus-visible,.ds-field input:focus-visible,.ds-nav button:focus-visible,.ds-chip:focus-visible,.ds-choice:focus-visible,.ds-audio-disc:focus-visible,.ds-text-teaser:focus-visible{outline:2px solid var(--accent, #b3d2f5);outline-offset:3px}@media(prefers-reduced-motion:reduce){button:active{transform:none!important}button{transition-duration:1ms!important;animation:none!important}}

.ds-choice{font-family:var(--font-ui, "Instrument Sans Variable", "Noto Serif SC", system-ui, sans-serif);color:var(--ink, #f0f3f5);border:0;cursor:pointer;width:100%}.ds-choice {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  min-height: 58px;
  padding: 12px 18px;
  border-radius: var(--r, 10px);
  background: var(--sheet, #17263a);
  box-shadow: inset 0 0 0 1px var(--rule, #304359);
  font-size: 17px;
  text-align: left;
  transition:
    background-color 160ms ease,
    box-shadow 160ms ease,
    opacity 200ms ease,
    transform 160ms var(--ease-out, cubic-bezier(0.23, 1, 0.32, 1));
}
.ds-choice:active:not(:disabled) {
  transform: scale(0.985);
}
.ds-choice-key {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 6px;
  box-shadow: inset 0 0 0 1px var(--rule-strong, #657f98);
  font-size: 13px;
  font-weight: 500;
  color: var(--ink-3, #aabccd);
  font-variant-numeric: tabular-nums;
}
.ds-choice.ds-selected {
  background: var(--accent-wash, #263d57);
  box-shadow: inset 0 0 0 1.5px var(--accent, #b3d2f5);
}
.ds-choice.ds-selected .ds-choice-key {
  background: var(--accent, #b3d2f5);
  color: var(--on-accent, #102238);
  box-shadow: none;
}
.ds-choice.ds-correct {
  background: var(--good-wash, #1b3937);
  box-shadow: inset 0 0 0 1.5px var(--good, #9bcdbc);
  color: var(--ink, #f0f3f5);
}
.ds-choice.ds-correct .ds-choice-key {
  background: var(--good, #9bcdbc);
  color: var(--on-accent, #102238);
  box-shadow: none;
}
.ds-choice.ds-incorrect {
  background: var(--bad-wash, #422d32);
  box-shadow: inset 0 0 0 1.5px var(--bad, #f2b29e);
}
.ds-choice.ds-dim {
  opacity: 0.5;
}
.ds-choice:disabled:not(.ds-correct):not(.ds-incorrect):not(.ds-dim) {
  opacity: 0.55;
}@media(hover:hover) and (pointer:fine){.ds-choice:hover:not(:disabled):not(.ds-selected){box-shadow:inset 0 0 0 1px var(--ink-4, #9aafc3)}}.ds-button:focus-visible,.ds-field input:focus-visible,.ds-nav button:focus-visible,.ds-chip:focus-visible,.ds-choice:focus-visible,.ds-audio-disc:focus-visible,.ds-text-teaser:focus-visible{outline:2px solid var(--accent, #b3d2f5);outline-offset:3px}@media(prefers-reduced-motion:reduce){button:active{transform:none!important}button{transition-duration:1ms!important;animation:none!important}}

.ds-audio-disc{border:0;cursor:pointer}.ds-audio-disc {
  width: 84px;
  height: 84px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--accent, #b3d2f5);
  color: var(--on-accent, #102238);
  transition:
    transform 160ms var(--ease-out, cubic-bezier(0.23, 1, 0.32, 1)),
    background-color 160ms ease;
}.ds-audio-disc:active {
  transform: scale(0.95);
}.ds-audio-disc.ds-is-playing {
  background: var(--ink, #f0f3f5);
}@media(hover:hover) and (pointer:fine){.ds-audio-disc:hover:not(.ds-is-playing) {
    background: var(--accent-hover, #d2e5fc);
  }}.ds-button:focus-visible,.ds-field input:focus-visible,.ds-nav button:focus-visible,.ds-chip:focus-visible,.ds-choice:focus-visible,.ds-audio-disc:focus-visible,.ds-text-teaser:focus-visible{outline:2px solid var(--accent, #b3d2f5);outline-offset:3px}@media(prefers-reduced-motion:reduce){button:active{transform:none!important}button{transition-duration:1ms!important;animation:none!important}}

.ds-text-teaser{font-family:var(--font-ui, "Instrument Sans Variable", "Noto Serif SC", system-ui, sans-serif);color:var(--ink, #f0f3f5);border:0;cursor:pointer;text-align:left}.ds-text-teaser [lang]{font-family:var(--font-han, "Noto Serif SC", "Songti SC", "STSong", serif)}.ds-text-teaser {
  width: 100%;
  display: grid;
  gap: 10px;
  padding: 22px 24px;
  background: var(--sheet, #17263a);
  border: 1px solid var(--rule, #304359);
  border-radius: var(--r, 10px);
  transition:
    border-color 160ms ease,
    transform 160ms var(--ease-out, cubic-bezier(0.23, 1, 0.32, 1));
}.ds-text-teaser:active {
  transform: scale(0.99);
}.ds-teaser-title {
  font-size: 15px;
  letter-spacing: 0.2em;
  color: var(--ink-3, #aabccd);
}.ds-teaser-line {
  font-size: 32px;
  line-height: 1.45;
  letter-spacing: 0.04em;
  color: var(--ink-3, #aabccd);
}.ds-teaser-line .ds-k {
  color: var(--ink, #f0f3f5);
}.ds-teaser-meta {
  font-size: 14px;
  color: var(--ink-3, #aabccd);
}@media(hover:hover) and (pointer:fine){.ds-text-teaser:hover {
    border-color: var(--rule-strong, #657f98);
  }}.ds-button:focus-visible,.ds-field input:focus-visible,.ds-nav button:focus-visible,.ds-chip:focus-visible,.ds-choice:focus-visible,.ds-audio-disc:focus-visible,.ds-text-teaser:focus-visible{outline:2px solid var(--accent, #b3d2f5);outline-offset:3px}@media(prefers-reduced-motion:reduce){button:active{transform:none!important}button{transition-duration:1ms!important;animation:none!important}}
